    ::sc::lowered::Tally tally("VehicleArt::make(kern::Renderer &, Part &, const MeshData &, const kern::Material &, bool)");
    ::sc::converted::Draw draw;
    for (int call = 0; tally.more(call); ++call) {
      ::sc_old_vehicle_art::sc::VehicleArt o_self{};
      if (draw.flag()) ::sc::lowered::draw(draw, o_self);
      ::sc_new_vehicle_art::sc::VehicleArt n_self{};
      ::sc::lowered::carry(o_self, n_self);
      ::sc::lowered::Arg<kern::Renderer &> o0;
      ::sc::lowered::Arg<kern::Renderer &> n0;
      ::sc::lowered::draw_pair(draw, o0, n0);
      ::sc::lowered::Arg<::sc_old_vehicle_art::sc::VehicleArt::Part &> o1;
      ::sc::lowered::Arg<::sc_new_vehicle_art::sc::VehicleArt::Part &> n1;
      ::sc::lowered::draw_pair(draw, o1, n1);
      ::sc::lowered::Arg<const MeshData &> o2;
      ::sc::lowered::Arg<const MeshData &> n2;
      ::sc::lowered::draw_pair(draw, o2, n2);
      ::sc::lowered::Arg<const kern::Material &> o3;
      ::sc::lowered::Arg<const kern::Material &> n3;
      ::sc::lowered::draw_pair(draw, o3, n3);
      ::sc::lowered::Arg<bool> o4;
      ::sc::lowered::Arg<bool> n4;
      ::sc::lowered::draw_pair(draw, o4, n4);
      std::optional<std::remove_cvref_t<decltype(o_self.make(o0.get(), o1.get(), o2.get(), o3.get(), o4.get()))>> o_r;
      std::optional<std::remove_cvref_t<decltype(n_self.make(n0.get(), n1.get(), n2.get(), n3.get(), n4.get()))>> n_r;
      long old_asks = 0, new_asks = 0;
      const bool old_defined = ::sc::lowered::run([&] { o_r.emplace(o_self.make(o0.get(), o1.get(), o2.get(), o3.get(), o4.get())); }, old_asks);
      const bool new_defined = ::sc::lowered::run([&] { n_r.emplace(n_self.make(n0.get(), n1.get(), n2.get(), n3.get(), n4.get())); }, new_asks);
      ::sc::lowered::Differs differs;
      differs.check("what it returns", o_r, n_r);
      differs.check("its object", o_self, n_self);
      differs.check("its parameter r", o0, n0);
      differs.check("its parameter p", o1, n1);
      tally.take(old_defined && new_defined, differs.text, old_asks, new_asks, call);
    }
